insert into public.tutors (slug, full_name, title, specialization, bio, experience, qualifications, expertise, socials, email, image_url, published, sort_order) values ('adaeze-okafor', 'Adaeze Okafor', 'Lead Instructor, Design', 'Graphic Design and UI/UX', 'Adaeze teaches visual design as a working discipline: briefs, constraints, feedback and delivery. Her classes are built around real client-style projects so learners leave with finished portfolio pieces.', 'Nine years in brand, packaging and product design for small businesses and start-ups.', '["B.A. Fine and Applied Arts","Certified UX practitioner","Mentor on design apprenticeship programmes"]'::jsonb, '["Brand identity","Typography","Interface design","Design systems","Portfolio review"]'::jsonb, '{"linkedin":"https://www.linkedin.com/","x":"https://x.com/","instagram":"https://www.instagram.com/"}'::jsonb, '', 'assets/images/tutors/adaeze-okafor.svg', true, 1) on conflict (slug) do nothing;
insert into public.tutors (slug, full_name, title, specialization, bio, experience, qualifications, expertise, socials, email, image_url, published, sort_order) values ('tunde-bakare', 'Tunde Bakare', 'Senior Instructor, Web Engineering', 'Frontend and Full Stack Development', 'Tunde helps beginners become dependable web developers. He focuses on fundamentals first, then on shipping projects with modern tooling and responsible use of AI assistants.', 'Eight years building web applications for fintech, education and logistics teams.', '["B.Sc. Computer Science","Open-source contributor","Conference speaker on web performance"]'::jsonb, '["HTML and CSS","JavaScript","Web performance","Accessibility","AI-assisted development"]'::jsonb, '{"linkedin":"https://www.linkedin.com/","x":"https://x.com/","instagram":"https://www.instagram.com/"}'::jsonb, '', 'assets/images/tutors/tunde-bakare.svg', true, 2) on conflict (slug) do nothing;
insert into public.tutors (slug, full_name, title, specialization, bio, experience, qualifications, expertise, socials, email, image_url, published, sort_order) values ('chinedu-eze', 'Chinedu Eze', 'Instructor, Backend Engineering', 'Backend Development and AI', 'Chinedu teaches how to design data models, build secure APIs and connect them to intelligent features. Expect code reviews, pair sessions and plenty of debugging practice.', 'Seven years designing APIs and databases for SaaS and payments products.', '["B.Eng. Electrical and Electronics","PostgreSQL specialist","API security workshop facilitator"]'::jsonb, '["REST APIs","PostgreSQL","Authentication","Cloud deployment","LLM integrations"]'::jsonb, '{"linkedin":"https://www.linkedin.com/","x":"https://x.com/","instagram":"https://www.instagram.com/"}'::jsonb, '', 'assets/images/tutors/chinedu-eze.svg', true, 3) on conflict (slug) do nothing;
insert into public.tutors (slug, full_name, title, specialization, bio, experience, qualifications, expertise, socials, email, image_url, published, sort_order) values ('halima-yusuf', 'Halima Yusuf', 'Instructor, Data', 'Data Analysis', 'Halima turns spreadsheets and messy datasets into clear stories. Her learners practise cleaning, analysing and presenting data the way business teams actually ask for it.', 'Six years as an analyst in retail, health and public-sector programmes.', '["B.Sc. Statistics","Certified data analytics associate"]'::jsonb, '["Spreadsheets","SQL","Data cleaning","Dashboards","Data storytelling"]'::jsonb, '{"linkedin":"https://www.linkedin.com/","x":"https://x.com/","instagram":"https://www.instagram.com/"}'::jsonb, '', 'assets/images/tutors/halima-yusuf.svg', true, 4) on conflict (slug) do nothing;
insert into public.tutors (slug, full_name, title, specialization, bio, experience, qualifications, expertise, socials, email, image_url, published, sort_order) values ('ibrahim-lawal', 'Ibrahim Lawal', 'Instructor, Security', 'Cybersecurity', 'Ibrahim makes security practical for beginners: understand how attacks work, protect accounts and devices, and build safer habits for individuals and small organisations.', 'Seven years in IT support, network administration and security awareness training.', '["B.Tech. Computer Engineering","Security fundamentals certified"]'::jsonb, '["Network basics","Threat awareness","Account security","Incident response basics","Security policy"]'::jsonb, '{"linkedin":"https://www.linkedin.com/","x":"https://x.com/","instagram":"https://www.instagram.com/"}'::jsonb, '', 'assets/images/tutors/ibrahim-lawal.svg', true, 5) on conflict (slug) do nothing;
insert into public.tutors (slug, full_name, title, specialization, bio, experience, qualifications, expertise, socials, email, image_url, published, sort_order) values ('ngozi-adeyemi', 'Ngozi Adeyemi', 'Instructor, Operations', 'Project Management and Virtual Assistance', 'Ngozi teaches the practical side of getting work done: planning, communication, tools and client service, for remote assistants and project coordinators alike.', 'Ten years coordinating projects and remote teams across several industries.', '["B.Sc. Business Administration","Project management practitioner certificate"]'::jsonb, '["Project planning","Remote collaboration","Client communication","Productivity tools","Reporting"]'::jsonb, '{"linkedin":"https://www.linkedin.com/","x":"https://x.com/","instagram":"https://www.instagram.com/"}'::jsonb, '', 'assets/images/tutors/ngozi-adeyemi.svg', true, 6) on conflict (slug) do nothing;
insert into public.tutors (slug, full_name, title, specialization, bio, experience, qualifications, expertise, socials, email, image_url, published, sort_order) values ('funmilayo-adebayo', 'Funmilayo Adebayo', 'Instructor, Wellbeing and Care', 'Mental Health and Child Safety', 'Funmilayo leads courses on wellbeing and safeguarding for parents, teachers and community workers, with clear guidance on when and how to involve professionals.', 'Eleven years in community education, counselling support and child welfare programmes.', '["B.Ed. Guidance and Counselling","Safeguarding training facilitator"]'::jsonb, '["Wellbeing awareness","Safeguarding","Parent education","Community outreach"]'::jsonb, '{"linkedin":"https://www.linkedin.com/","x":"https://x.com/","instagram":"https://www.instagram.com/"}'::jsonb, '', 'assets/images/tutors/funmilayo-adebayo.svg', true, 7) on conflict (slug) do nothing;
insert into public.courses (slug, title, category, icon, short_description, description, duration, price, currency, tutor_id, image_url, outcomes, requirements, faqs, assessment_info, certificate_info, featured, published, sort_order) values ('graphic-design', 'Graphic Design', 'Design', 'design', 'Learn layout, colour, typography and brand identity by producing real design briefs.', 'This programme takes you from design principles to finished work: logos, social media kits, print layouts and a brand identity project. You will practise giving and receiving feedback and end with a portfolio you can show to clients and employers.', '8 weeks', 60000, 'NGN', (select id from public.tutors where slug = 'adaeze-okafor'), 'assets/images/courses/graphic-design.svg', '["Design balanced layouts with clear hierarchy","Create a logo and a simple brand guideline","Prepare artwork for print and screens","Present design decisions to a client"]'::jsonb, '["A laptop or desktop computer","Willingness to complete weekly design exercises"]'::jsonb, '[{"q":"Do I need prior experience?","a":"No. Every programme starts from the basics unless the requirements say otherwise."},{"q":"How do I pay and get access?","a":"Enrol on this page, then complete payment. Lessons unlock only after your payment has been verified."},{"q":"Can I study on my phone?","a":"Yes. The learning platform works on phones, tablets and laptops."},{"q":"How do I get my certificate?","a":"Finish all lessons, assignments and examinations. Your certificate then appears in your dashboard."}]'::jsonb, 'Assessment combines weekly assignments and a final examination. To be eligible for a certificate you complete every lesson, submit every assignment and pass each examination (pass mark 50%).', 'On completion you receive a Courssins Technology Institute certificate with a unique number that anyone can check on our public verification page.', true, true, 1) on conflict (slug) do nothing;
