insert into public.courses (slug, title, category, icon, short_description, description, duration, price, currency, tutor_id, image_url, outcomes, requirements, faqs, assessment_info, certificate_info, featured, published, sort_order) values ('frontend-web-development-and-ai', 'Frontend Web Development and AI', 'Development', 'code', 'Build fast, accessible websites with HTML, CSS and JavaScript, and learn to use AI tools responsibly.', 'Start with semantic HTML and modern CSS, move into JavaScript and APIs, then deploy real projects. The final module shows how to use AI assistants to speed up work without losing understanding of your own code.', '12 weeks', 120000, 'NGN', (select id from public.tutors where slug = 'tunde-bakare'), 'assets/images/courses/frontend-web-development-and-ai.svg', '["Build responsive, accessible interfaces","Write and debug JavaScript confidently","Publish projects with Git and Vercel","Use AI assistants to learn and ship faster"]'::jsonb, '["A laptop or desktop computer","Basic computer skills; no coding experience needed"]'::jsonb, '[{"q":"Do I need prior experience?","a":"No. Every programme starts from the basics unless the requirements say otherwise."},{"q":"How do I pay and get access?","a":"Enrol on this page, then complete payment. Lessons unlock only after your payment has been verified."},{"q":"Can I study on my phone?","a":"Yes. The learning platform works on phones, tablets and laptops."},{"q":"How do I get my certificate?","a":"Finish all lessons, assignments and examinations. Your certificate then appears in your dashboard."}]'::jsonb, 'Assessment combines weekly assignments and a final examination. To be eligible for a certificate you complete every lesson, submit every assignment and pass each examination (pass mark 50%).', 'On completion you receive a Courssins Technology Institute certificate with a unique number that anyone can check on our public verification page.', true, true, 2) on conflict (slug) do nothing;
