insert into public.courses (slug, title, category, icon, short_description, description, duration, price, currency, tutor_id, image_url, outcomes, requirements, faqs, assessment_info, certificate_info, featured, published, sort_order) values ('backend-development-and-ai', 'Backend Development and AI', 'Development', 'server', 'Design databases and secure APIs, then connect them to AI-powered features.', 'Learn how servers, databases and APIs work together. You will model data in PostgreSQL, build authenticated APIs and integrate a language model into a working product.', '12 weeks', 120000, 'NGN', (select id from public.tutors where slug = 'chinedu-eze'), 'assets/images/courses/backend-development-and-ai.svg', '["Design relational database schemas","Build and secure REST APIs","Integrate an AI model into an application","Deploy and monitor a backend service"]'::jsonb, '["Basic programming knowledge is helpful","A laptop or desktop computer"]'::jsonb, '[{"q":"Do I need prior experience?","a":"No. Every programme starts from the basics unless the requirements say otherwise."},{"q":"How do I pay and get access?","a":"Enrol on this page, then complete payment. Lessons unlock only after your payment has been verified."},{"q":"Can I study on my phone?","a":"Yes. The learning platform works on phones, tablets and laptops."},{"q":"How do I get my certificate?","a":"Finish all lessons, assignments and examinations. Your certificate then appears in your dashboard."}]'::jsonb, 'Assessment combines weekly assignments and a final examination. To be eligible for a certificate you complete every lesson, submit every assignment and pass each examination (pass mark 50%).', 'On completion you receive a Courssins Technology Institute certificate with a unique number that anyone can check on our public verification page.', false, true, 3) on conflict (slug) do nothing;
