insert into public.courses (slug, title, category, icon, short_description, description, duration, price, currency, tutor_id, image_url, outcomes, requirements, faqs, assessment_info, certificate_info, featured, published, sort_order) values ('full-stack-development', 'Full Stack Development', 'Development', 'stack', 'Combine frontend and backend skills to plan, build and launch complete web applications.', 'A longer programme for people who want to build entire products. You will design interfaces, build the data layer, add authentication and payments-ready flows, and launch a capstone project.', '16 weeks', 200000, 'NGN', (select id from public.tutors where slug = 'tunde-bakare'), 'assets/images/courses/full-stack-development.svg', '["Plan and build a complete web application","Implement login, roles and permissions","Work in a team using Git","Launch and present a capstone project"]'::jsonb, '["Comfort using a computer","Commitment of about 10 hours per week"]'::jsonb, '[{"q":"Do I need prior experience?","a":"No. Every programme starts from the basics unless the requirements say otherwise."},{"q":"How do I pay and get access?","a":"Enrol on this page, then complete payment. Lessons unlock only after your payment has been verified."},{"q":"Can I study on my phone?","a":"Yes. The learning platform works on phones, tablets and laptops."},{"q":"How do I get my certificate?","a":"Finish all lessons, assignments and examinations. Your certificate then appears in your dashboard."}]'::jsonb, 'Assessment combines weekly assignments and a final examination. To be eligible for a certificate you complete every lesson, submit every assignment and pass each examination (pass mark 50%).', 'On completion you receive a Courssins Technology Institute certificate with a unique number that anyone can check on our public verification page.', true, true, 4) on conflict (slug) do nothing;
